def adaptive_simpson(f, a, b, tol):
    def simpson(a, b):
        c = (a + b) / 2
        return (b - a) / 6 * (f(a) + 4*f(c) + f(b))
    def recurse(a, b, whole, tol):
        c = (a + b) / 2
        left, right = simpson(a, c), simpson(c, b)
        if abs(left + right - whole) <= 15 * tol:
            return left + right + (left + right - whole) / 15
        return recurse(a, c, left, tol/2) + recurse(c, b, right, tol/2)
    return recurse(a, b, simpson(a, b), tol)

def richardson(A, h, p, levels):
    # A(h) is a function returning the approximation at step h
    T = [[0.0]*(levels) for _ in range(levels)]
    for i in range(levels):
        T[i][0] = A(h / 2**i)
    for j in range(1, levels):
        for i in range(j, levels):
            f = 2.0**(p*j)
            T[i][j] = (f * T[i][j-1] - T[i-1][j-1]) / (f - 1)
    return T[levels-1][levels-1]

def rk4_step(f, t, y, h):
    k1 = f(t, y)
    k2 = f(t + h/2, y + h/2 * k1)
    k3 = f(t + h/2, y + h/2 * k2)
    k4 = f(t + h,   y + h   * k3)
    return y + h/6 * (k1 + 2*k2 + 2*k3 + k4)
